#!/usr/bin/python3
import importlib.util, io, os, tempfile, threading, time, unittest
from pathlib import Path
E=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('fixture',E/'run-app.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)

class DrainChecks(unittest.TestCase):
    def test_writer_failure_reaches_controller(self):
        with tempfile.TemporaryDirectory(dir=E) as tmp:
            old=threading.excepthook
            try:
                threading.excepthook=lambda args:None
                drain=m.Drain(io.BytesIO(b'evidence'),Path(tmp)/'absent'/'log')
                with self.assertRaises((OSError,ValueError)):drain.finish()
            finally:threading.excepthook=old
    def test_live_short_write_does_not_wait_for_eof(self):
        with tempfile.TemporaryDirectory(dir=E) as tmp:
            r,w=os.pipe();source=os.fdopen(r,'rb');path=Path(tmp)/'log'
            try:
                drain=m.Drain(source,path);os.write(w,b'first event\n')
                deadline=time.monotonic()+2
                while time.monotonic()<deadline and (not path.exists() or path.stat().st_size==0):time.sleep(.01)
                self.assertEqual(path.read_bytes(),b'first event\n')
            finally:os.close(w);drain.finish();source.close()
    def test_overflow_remains_failure(self):
        with tempfile.TemporaryDirectory(dir=E) as tmp:
            path=Path(tmp)/'log';drain=m.Drain(io.BytesIO(b'x'*(8*1024**2+1)),path)
            with self.assertRaises(ValueError):drain.finish()
            self.assertEqual(path.stat().st_size,8*1024**2)

class OwnershipChecks(unittest.TestCase):
    def observe(self, status, reply):
        with tempfile.TemporaryDirectory(dir=E) as tmp:
            p=Path(tmp);(p/'run').mkdir()
            (p/'run/dconf-owner-before.status').write_text(status)
            (p/'run/dconf-owner-before.txt').write_text(reply)
            return m.dconf_owned(p,'before')
    def test_zero_status_exact_true(self):
        self.assertTrue(self.observe('0\n','method return\n   boolean true\n'))
    def test_nonzero_status_cannot_publish_true(self):
        self.assertFalse(self.observe('1\n','method return\n   boolean true\n'))
    def test_false_duplicate_and_embedded_text_refused(self):
        for reply in ['   boolean false\n','boolean true\nboolean true\n','error: boolean true']:
            with self.subTest(reply=reply):self.assertFalse(self.observe('0\n',reply))

if __name__=='__main__':unittest.main()
